      "url": "https://img.itch.zone/aW1hZ2UvOTg5MTU0LzU2NjU2MDAucG5n/original/MnHlHT.png",
      "local_path": "screenshots/61a2cfb11e537bf4a70ef54b5b709945ccceb45d1029f99054d94fefa1518407.png",
